-- 苫小牧埠頭野球部 v3.3 Supabase初期設定
-- このSQLはSupabaseのSQL Editorで1回だけ実行します。
create extension if not exists pgcrypto;

create table if not exists public.app_state (
  id integer primary key,
  data jsonb not null,
  updated_at timestamptz not null default now()
);

create table if not exists public.app_security (
  id integer primary key,
  admin_password_hash text not null,
  updated_at timestamptz not null default now()
);

alter table public.app_state enable row level security;
alter table public.app_security enable row level security;

drop policy if exists "public read app state" on public.app_state;
create policy "public read app state" on public.app_state for select to anon, authenticated using (true);

revoke insert, update, delete on public.app_state from anon, authenticated;
revoke all on public.app_security from anon, authenticated;

drop function if exists public.verify_admin_password(text);
create or replace function public.verify_admin_password(p_password text)
returns boolean language sql security definer set search_path = public, extensions
as $$ select exists(select 1 from public.app_security where id=1 and admin_password_hash = crypt(p_password, admin_password_hash)); $$;
grant execute on function public.verify_admin_password(text) to anon, authenticated;

drop function if exists public.save_app_state(text,jsonb);
create or replace function public.save_app_state(p_password text, p_data jsonb)
returns boolean language plpgsql security definer set search_path = public, extensions
as $$
begin
  if not exists(select 1 from public.app_security where id=1 and admin_password_hash = crypt(p_password, admin_password_hash)) then return false; end if;
  insert into public.app_state(id,data,updated_at) values(1,p_data,now())
  on conflict(id) do update set data=excluded.data, updated_at=now();
  return true;
end; $$;
grant execute on function public.save_app_state(text,jsonb) to anon, authenticated;

drop function if exists public.change_admin_password(text,text);
create or replace function public.change_admin_password(p_old_password text, p_new_password text)
returns boolean language plpgsql security definer set search_path = public, extensions
as $$
begin
  if length(coalesce(p_new_password,'')) < 4 then return false; end if;
  if not exists(select 1 from public.app_security where id=1 and admin_password_hash = crypt(p_old_password, admin_password_hash)) then return false; end if;
  update public.app_security set admin_password_hash=crypt(p_new_password, gen_salt('bf')), updated_at=now() where id=1;
  return true;
end; $$;
grant execute on function public.change_admin_password(text,text) to anon, authenticated;

drop function if exists public.update_attendance(bigint,bigint,text,text);
create or replace function public.update_attendance(p_event_id bigint, p_player_id bigint, p_status text, p_note text default '')
returns boolean language plpgsql security definer set search_path = public
as $$
declare new_events jsonb;
begin
  if p_status not in ('参加','欠席','未回答') then return false; end if;
  select coalesce(jsonb_agg(
    case when (e->>'id')::bigint = p_event_id then
      jsonb_set(
        jsonb_set(e, '{attendance}', coalesce(e->'attendance','{}'::jsonb) || jsonb_build_object(p_player_id::text,p_status), true),
        '{attendanceNotes}', coalesce(e->'attendanceNotes','{}'::jsonb) || jsonb_build_object(p_player_id::text,coalesce(p_note,'')), true
      )
    else e end
  ), '[]'::jsonb) into new_events
  from jsonb_array_elements(coalesce((select data->'events' from public.app_state where id=1),'[]'::jsonb)) e;
  update public.app_state set data=jsonb_set(data,'{events}',new_events,true),updated_at=now() where id=1;
  return found;
end; $$;
grant execute on function public.update_attendance(bigint,bigint,text,text) to anon, authenticated;

